// Module 13 evidence: installs one real appliance from a package generated by the dev stack (custom-REST PSA
// pointing at the fake PSA, its own process), verifies the connection, then issues every remote command type
// from the Control Plane API and lets the real agent / worker execute them; applies the staged upgrade on the
// host with the package's scripts/upgrade.sh; captures the Operations tab (cards, issue panel, history), the
// appliance dashboard (remote commands + staged upgrade), the health page action and the activity log.
// Requires the dev API on the host address and EDGE_IMAGE_VERSION=0.1.0-next in apps/api/.env (the appliance
// is installed on psacc/psa-edge:0.1.0 so the upgrade is real). Usage: node scripts/screenshots-m13.mjs
import { spawn, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-13/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const hostIp = sh(`ip -4 route get 1.1.1.1 | awk '{for(i=1;i<=NF;i++) if($i=="src") print $(i+1)}'`).out;
const BASE_IMAGE = 'psacc/psa-edge:0.1.0';

const API_KEY = `demo-${Math.random().toString(36).slice(2, 10)}`;
const caPath = join(realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m13ca-'))), 'ca.pem');
const fake = spawn(process.execPath, [fileURLToPath(new URL('./fake-psa.mjs', import.meta.url)), hostIp, API_KEY, caPath], { stdio: ['ignore', 'pipe', 'inherit'] });
const port = await new Promise((resolve, reject) => {
  fake.stdout.on('data', (d) => { for (const line of String(d).split(/\r?\n/)) { const m = /^PORT (\d+)$/.exec(line); if (m) resolve(Number(m[1])); } });
  fake.on('exit', (code) => reject(new Error(`fake PSA exited with ${code}`)));
});

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};

const image = await api('GET', '/deployments/edge-image');
if (image.version === '0.1.0') throw new Error('Set EDGE_IMAGE_VERSION=0.1.0-next in apps/api/.env and restart the dev API so the upgrade is real.');
const client = (await api('GET', '/clients?status=active&pageSize=50')).items.find((c) => c.code !== 'CL-00001');
const services = await api('GET', `/clients/${client.id}/services`);
const instance = await api('POST', '/psa-instances', {
  clientId: client.id, providerKey: 'custom_rest', displayName: `${client.displayName} — Demo PSA ${Date.now().toString(36)}`, authMethod: 'api_key',
  config: { baseUrl: `https://${hostIp}:${port}/api`, healthPath: '/health', apiKeyHeader: 'X-API-Key', ticketsPath: '/tickets' }, enabledServiceIds: services.filter((s) => s.requiresPsa).map((s) => s.id),
});
const dep = await api('POST', '/deployments', { clientId: client.id, psaInstanceId: instance.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module13-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m13-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m13shots/${project}`;
const adminPort = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unix = (p) => sh(`wslpath -a '${p}'`).out;
const adminBase = `http://127.0.0.1:${adminPort}`;
const curl = (args) => sh(`curl -s -o /tmp/psacc-m13shots/body -w '%{http_code}' -b /tmp/psacc-m13shots/jar -c /tmp/psacc-m13shots/jar ${args}; echo; cat /tmp/psacc-m13shots/body`, 60_000).out;
const waitFor = async (fn, ms, label) => { const end = Date.now() + ms; while (Date.now() < end) { if (await fn()) return; await sleep(2000); } throw new Error(`timed out: ${label}`); };
const command = async (id) => (await api('GET', `/deployments/${dep.id}/operations?limit=100`)).commands.find((c) => c.id === id);
const issue = async (type, params) => (await api('POST', `/deployments/${dep.id}/commands`, { type, ...(params ? { params } : {}), expiresInMinutes: 60, note: `Demo: ${type}` })).id;
const settled = async (id, label) => { await waitFor(async () => ['succeeded', 'failed', 'staged'].includes((await command(id)).status), 150_000, label); return command(id); };

try {
  let r = sh(`rm -rf /tmp/psacc-m13shots && mkdir -p /tmp/psacc-m13shots && cd /tmp/psacc-m13shots && unzip -q "${unix(join(winTmp, pkg.fileName))}" && cd ${project} && cp config/edge.env.template .env && echo PSA_EDGE_IMAGE=${BASE_IMAGE} >> .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).lifecycleState === 'verified', 180_000, 'verified');
  const pw = `demo-${dep.code}-local-admin-pass`;
  curl(`-X POST --data-urlencode username=localadmin --data-urlencode password=${pw} --data-urlencode confirm=${pw} ${adminBase}/setup`);
  const token = /name="csrf" value="([^"]+)"/.exec(curl(`${adminBase}/credentials`))[1];
  curl(`-X POST --data-urlencode csrf=${token} --data-urlencode field_apiKey=${API_KEY} --data-urlencode "field_tlsCaCertificate@${unix(caPath)}" ${adminBase}/credentials`);
  if (!curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`).includes('Connection verified')) throw new Error('the appliance test did not verify');
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}/operations`)).runningVersion === '0.1.0', 90_000, 'version reported');

  await page.goto(`${base}/deployments/${dep.id}/operations`, { waitUntil: 'networkidle' });
  await shot(page, '01-operations-tab');
  await page.getByTestId('command-restart_service').click();
  await page.getByTestId('command-service').selectOption('edge-worker');
  await page.getByLabel('Note (kept with the audit record)').fill('Worker stuck after maintenance window');
  await page.waitForTimeout(300);
  await shot(page, '02-issue-panel-inline-confirmation');
  await page.getByTestId('issue-command').click();
  await page.waitForTimeout(800);
  const restartId = (await api('GET', `/deployments/${dep.id}/operations`)).commands[0].id;
  console.log('restart', (await settled(restartId, 'restart')).status);
  for (const t of ['refresh_health', 'test_psa_connection', 'run_sync', 'rotate_certificate']) console.log(t, (await settled(await issue(t), t)).status);
  const upId = await issue('upgrade');
  console.log('upgrade', (await settled(upId, 'upgrade staged')).status);
  await page.goto(`${base}/deployments/${dep.id}/operations`, { waitUntil: 'networkidle' });
  await shot(page, '03-command-history-staged-upgrade');

  const edge = await browser.newContext({ viewport: { width: 1200, height: 900 }, deviceScaleFactor: 2 });
  const ep = await edge.newPage();
  await ep.goto(`http://localhost:${adminPort}/login`);
  await ep.getByLabel('User name').fill('localadmin');
  await ep.getByLabel('Password').fill(pw);
  await ep.getByRole('button', { name: 'Sign in' }).click();
  const status = await (await ep.request.get(`http://localhost:${adminPort}/api/status`)).json();
  writeFileSync(`${outDir}appliance-status-remote.json`, JSON.stringify(status.remote, null, 2));
  console.log('appliance status remote:', JSON.stringify(status.remote).slice(0, 400));
  await ep.goto(`http://localhost:${adminPort}/`, { waitUntil: 'networkidle' });
  const dash = await ep.content();
  console.log('dashboard has section:', dash.includes('Remote commands'), 'staged notice:', dash.includes('staged-upgrade'));
  if (!dash.includes('staged-upgrade')) {
    console.log('dashboard tail:', dash.slice(-600).replace(/\s+/g, ' '));
    console.log('render errors:', sh(`cd ${work} && docker compose -f compose.yaml logs --no-log-prefix edge-api 2>&1 | grep -i 'render failed' | tail -3`).out.slice(0, 1200));
  }
  await ep.getByRole('heading', { name: 'Remote commands' }).scrollIntoViewIfNeeded();
  await shot(ep, '04-appliance-remote-commands-staged-upgrade');
  await edge.close();

  // The host operator applies the staged upgrade with the package script.
  r = sh(`cd ${work} && scripts/upgrade.sh`, 400_000);
  if (r.code !== 0) throw new Error(`upgrade.sh failed: ${r.err || r.out}`);
  writeFileSync(`${outDir}upgrade-sh-output.txt`, `$ scripts/upgrade.sh\n${r.out}\n`);
  await waitFor(async () => ['succeeded', 'failed'].includes((await command(upId)).status), 150_000, 'upgrade applied');
  console.log('upgrade applied', (await command(upId)).status);
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}/operations`)).upToDate === true, 120_000, 'new version reported');
  await page.goto(`${base}/deployments/${dep.id}/operations`, { waitUntil: 'networkidle' });
  await shot(page, '05-upgrade-applied-up-to-date');
  await page.goto(`${base}/deployments/${dep.id}/health`, { waitUntil: 'networkidle' });
  await page.getByTestId('report-now').click();
  await page.getByRole('status').waitFor();
  await shot(page, '06-health-report-now', false);
  await page.goto(`${base}/deployments/${dep.id}/logs`, { waitUntil: 'networkidle' });
  await shot(page, '07-activity-command-audit');

  const ops = await api('GET', `/deployments/${dep.id}/operations?limit=100`);
  writeFileSync(`${outDir}operations-sample.json`, JSON.stringify({ runningVersion: ops.runningVersion, upToDate: ops.upToDate, upgradeTarget: ops.upgradeTarget, signingKeyId: ops.signingKeyId, commands: ops.commands.map((c) => ({ type: c.type, status: c.status, params: c.params, issuedAt: c.issuedAt, deliveredAt: c.deliveredAt, finishedAt: c.finishedAt, result: c.result })) }, null, 2));
  writeFileSync(`${outDir}appliance-agent-status.json`, JSON.stringify(JSON.parse(sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-agent edge-agent status`).out).commands, null, 2));
} finally {
  sh(`cd ${work} && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m13shots`);
  rmSync(winTmp, { recursive: true, force: true });
  fake.kill('SIGTERM');
  rmSync(caPath, { force: true });
  await browser.close();
}
